import{_ as r,o,c as d,ah as e}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-10-05T00:00:00.000Z"},"headers":[{"level":3,"title":"1. 단계적 소통 해금","slug":"_1-단계적-소통-해금","link":"#_1-단계적-소통-해금","children":[]},{"level":3,"title":"2. 단계 전환 기준","slug":"_2-단계-전환-기준","link":"#_2-단계-전환-기준","children":[]},{"level":3,"title":"3. 3단계: 질문자가 답변 글자 수 선택","slug":"_3-3단계-질문자가-답변-글자-수-선택","link":"#_3-3단계-질문자가-답변-글자-수-선택","children":[]},{"level":3,"title":"4. 동시 매칭 인원 상한","slug":"_4-동시-매칭-인원-상한","link":"#_4-동시-매칭-인원-상한","children":[]},{"level":3,"title":"5. 일기 하루 1개 제한","slug":"_5-일기-하루-1개-제한","link":"#_5-일기-하루-1개-제한","children":[]},{"level":3,"title":"6. 매칭 전 \\"절반 공개\\"","slug":"_6-매칭-전-절반-공개","link":"#_6-매칭-전-절반-공개","children":[]},{"level":3,"title":"7. 번역 제한은 채팅에만","slug":"_7-번역-제한은-채팅에만","link":"#_7-번역-제한은-채팅에만","children":[]},{"level":3,"title":"8. 신원 검증 범위","slug":"_8-신원-검증-범위","link":"#_8-신원-검증-범위","children":[]},{"level":3,"title":"9. 비즈니스 모델","slug":"_9-비즈니스-모델","link":"#_9-비즈니스-모델","children":[]},{"level":3,"title":"10. 글감(프롬프트) 기능: 보류","slug":"_10-글감-프롬프트-기능-보류","link":"#_10-글감-프롬프트-기능-보류","children":[]},{"level":3,"title":"아직 안 정한 것","slug":"아직-안-정한-것","link":"#아직-안-정한-것","children":[]}],"relativePath":"computer/project/Zing/08. 기획 결정 기록 (2026-10-02).md","filePath":"computer/project/Zing/08. 기획 결정 기록 (2026-10-02).md"}'),l={name:"computer/project/Zing/08. 기획 결정 기록 (2026-10-02).md"};function n(i,t,a,s,g,u){return o(),d("div",null,[...t[0]||(t[0]=[e('<p>2026-10-02에 정한 <strong>기획/정책 결정</strong>을 &quot;결론 → 이유 → 기각한 안&quot; 순서로 남긴다. 최종 수치와 규칙은 <a href="/TIL/computer/project/Zing/기능명세서.html">기능명세서</a>가 기준이고, 여기에는 <strong>왜 그렇게 정했는지</strong>를 적는다. 코드로 한 작업은 <a href="/TIL/computer/project/Zing/07. 화면 구현과 네비게이션, 일기 작성, 피드 (2026-10-02).html">07번 노트</a>에 있다.</p><table tabindex="0"><thead><tr><th>#</th><th>결정</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td>단계적 소통 해금 (4단계, 점진적 추가)</td><td>확정 (전환 개수 2/4/7은 초안)</td></tr><tr><td>2</td><td>단계 전환 기준: 매칭 후 둘 다 쓴 일기 개수</td><td>확정 (개수는 초안)</td></tr><tr><td>3</td><td>3단계: 질문자가 답변 글자 수 선택 (5/20/100자)</td><td>확정</td></tr><tr><td>4</td><td>동시 매칭 상한 3명 + 4단계 도달 매칭당 +1</td><td>확정</td></tr><tr><td>5</td><td>일기 하루 1개 제한</td><td>확정, 구현 완료</td></tr><tr><td>6</td><td>매칭 전 절반 공개 (글자 수 기준)</td><td>확정, 구현 완료</td></tr><tr><td>7</td><td>번역 제한은 채팅에만</td><td>확정 (BM 세부 횟수는 미정)</td></tr><tr><td>8</td><td>신원 검증은 학교 소속만</td><td>확정, 구현은 런칭 전</td></tr><tr><td>9</td><td>BM: 핵심 무료 + 부가 기능 유료, 초기엔 전부 무료</td><td>방향 확정, 수치 미정</td></tr><tr><td>10</td><td>글감(프롬프트) 기능</td><td>보류</td></tr></tbody></table><hr><h3 id="_1-단계적-소통-해금" tabindex="-1">1. 단계적 소통 해금 <a class="header-anchor" href="#_1-단계적-소통-해금" aria-label="Permalink to &quot;1. 단계적 소통 해금&quot;">​</a></h3><p><strong>결론</strong>: 매칭되면 처음부터 자유롭게 대화하는 게 아니라, 관계가 쌓일수록 소통 수단이 하나씩 열린다.</p><table tabindex="0"><thead><tr><th>단계</th><th>추가되는 것</th><th>질문 출처</th><th>답변 길이</th></tr></thead><tbody><tr><td>1</td><td>반응(이모지)</td><td>-</td><td>-</td></tr><tr><td>2</td><td>+ 질문-답변</td><td>앱이 매일 제공</td><td>5자</td></tr><tr><td>3</td><td>+ 질문-답변(서로 작성)</td><td>유저가 직접 작성 (7자)</td><td>질문자가 5/20/100자 중 선택</td></tr><tr><td>4</td><td>+ 자유 채팅</td><td>틀 없음</td><td>제한 없음 (번역 지원)</td></tr><tr><td>5</td><td>+ 사진 공유</td><td>-</td><td>1차 범위 제외, 계획만</td></tr></tbody></table><p><strong>왜 이렇게 했나</strong></p><ul><li>이 앱의 정체성은 비동기, 글쓰기 기반의 &quot;교환일기&quot;다. 처음부터 채팅을 열면 카카오톡과 다를 게 없어진다. 그래서 일기 정체성을 지키면서 소통 욕구를 채우는 <strong>절충안</strong>으로 단계를 뒀다.</li><li><strong>&quot;기능 진화&quot;가 아니라 &quot;점진적 추가&quot;</strong>: 다음 단계가 열려도 앞 단계 기능은 사라지지 않고 쌓인다. 반응은 4단계에서도 계속 쓸 수 있다.</li><li><strong>제한 자체가 즐거움</strong>: 5자 같은 짧은 제한은 불편함이 아니라 &quot;틀 안에서 압축해 표현하는 재미&quot;(트위터, 식스워드 스토리)로 설계했다. 그래서 단계가 올라가도 이전 단계의 제한된 소통을 억지로 없애지 않는다.</li><li><strong>앱 안에 머물 이유</strong>: 카톡으로 빠져나가지 않게 하는 유인이 필요하다. 카톡에 없는 두 가지, ① 번역 ② 구조화된 질문-답변 게임을 마지막 단계까지 유지한다.</li><li>5단계(사진)는 Supabase Storage 같은 새 인프라가 필요해 개발 비용이 커서 1차 런칭에서 뺐다.</li><li>신고/차단은 모든 단계에서 항상 있어야 한다.</li></ul><p><strong>기각한 안</strong></p><ul><li><strong>댓글 방식의 소통</strong>: 댓글 대신 &quot;질문 하나에 짧은 답(3~5자)&quot;으로 하는 쪽이 제한의 즐거움을 살리고 부담도 적다고 보고 질문-답변으로 정했다.</li><li><strong>처음부터 자유 채팅</strong>: 위의 이유(카톡과 차별성 없음)로 제외.</li></ul><h3 id="_2-단계-전환-기준" tabindex="-1">2. 단계 전환 기준 <a class="header-anchor" href="#_2-단계-전환-기준" aria-label="Permalink to &quot;2. 단계 전환 기준&quot;">​</a></h3><table tabindex="0"><thead><tr><th>전환</th><th>조건</th></tr></thead><tbody><tr><td>1 → 2</td><td>매칭 후 둘 다 일기 2개 이상</td></tr><tr><td>2 → 3</td><td>매칭 후 둘 다 일기 4개 이상</td></tr><tr><td>3 → 4</td><td>매칭 후 둘 다 일기 7개 이상</td></tr></tbody></table><p><strong>왜 이렇게 했나</strong></p><ul><li><strong>날짜가 아니라 &quot;매칭 이후 각자 쓴 일기 개수&quot;</strong>: 실제 관계 활동량을 더 잘 반영한다. <code>diaries.author_id</code>와 <code>created_at</code>으로 매칭 이후 작성분만 세면 돼서 구현도 어렵지 않다.</li><li><strong>&quot;둘 다&quot;</strong>: 한쪽만 활발하고 한쪽이 방치하면 단계가 안 넘어간다. 의도된 동작이다.</li><li>2/4/7은 <strong>초안</strong>이다. 실제 적용 전에 재검토한다.</li></ul><p><strong>기각한 안</strong></p><ul><li><strong>일(날짜) 기준 해금</strong>: 활동 없이 시간만 지나도 단계가 올라가서 관계의 깊이를 반영하지 못한다.</li></ul><h3 id="_3-3단계-질문자가-답변-글자-수-선택" tabindex="-1">3. 3단계: 질문자가 답변 글자 수 선택 <a class="header-anchor" href="#_3-3단계-질문자가-답변-글자-수-선택" aria-label="Permalink to &quot;3. 3단계: 질문자가 답변 글자 수 선택&quot;">​</a></h3><p><strong>결론</strong>: 질문을 만들 때 답변 제한을 <strong>5자 / 20자 / 100자</strong> 중 하나로 고른다 (공백 포함, 기존 <code>char_count</code> 계산과 동일).</p><p><strong>왜 이렇게 했나</strong></p><ul><li>3단계의 핵심은 글자 수가 아니라 <strong>&quot;누가 질문을 만드느냐&quot;</strong>(앱에서 유저 자신으로)다.</li><li>질문자가 관계의 깊이를 스스로 조절하는 느낌을 준다.</li><li><strong>100자를 상한</strong>으로 둔 건 일기 최소 글자 수(200자), 4단계(자유 채팅)와 확실히 구분하려는 것. 3단계가 &quot;틀이 있는 소통&quot;이라는 정체성을 유지한다.</li><li>DB 설계 시 질문마다 답변 제한값을 저장할 필드가 필요하다 (<code>zings</code>/<code>messages</code> 구현 때 반영).</li></ul><h3 id="_4-동시-매칭-인원-상한" tabindex="-1">4. 동시 매칭 인원 상한 <a class="header-anchor" href="#_4-동시-매칭-인원-상한" aria-label="Permalink to &quot;4. 동시 매칭 인원 상한&quot;">​</a></h3><p><strong>결론</strong>: 기본 <strong>3명</strong>, <strong>4단계에 도달한 매칭마다 +1명</strong>.</p><p><strong>왜 이렇게 했나</strong></p><ul><li>관계를 깊게 만들수록 새 매칭 여유가 늘어나는 구조라, 많이 만나는 것보다 깊게 가는 쪽에 보상이 간다.</li><li>번역 API는 매칭된 상대와 소통할 때만 쓰이므로, 상한 자체가 <strong>API 비용을 자연스럽게 억제</strong>한다.</li><li>기본 3명이 무료 기준이고, 추가 확장은 유료 후보(BM 참고).</li><li>체크는 <code>sendZing</code> 함수 안에서 구현 예정 (아직 <code>zings</code> 테이블 없음).</li></ul><h3 id="_5-일기-하루-1개-제한" tabindex="-1">5. 일기 하루 1개 제한 <a class="header-anchor" href="#_5-일기-하루-1개-제한" aria-label="Permalink to &quot;5. 일기 하루 1개 제한&quot;">​</a></h3><p><strong>결론</strong>: 하루에 일기를 1개만 쓸 수 있다 (로컬 자정 기준).</p><p><strong>왜</strong>: 해금을 &quot;작성한 일기 개수&quot;로 판단하기로 하면서 필요해졌다. 제한이 없으면 한 번에 여러 개를 몰아 써서 단계를 부정하게 빨리 통과할 수 있다.</p><p><strong>구현</strong>: <code>createDiary</code>에서 오늘 쓴 일기가 있는지 확인하고 있으면 에러를 반환한다. 화면에서 같은 날 두 번째 저장이 막히는 것까지 확인했다.</p><h3 id="_6-매칭-전-절반-공개" tabindex="-1">6. 매칭 전 &quot;절반 공개&quot; <a class="header-anchor" href="#_6-매칭-전-절반-공개" aria-label="Permalink to &quot;6. 매칭 전 &quot;절반 공개&quot;&quot;">​</a></h3><p><strong>결론</strong>: 상호 징이 성사되면 전체 공개, 그 전에는 <strong>글자 수 기준 정확히 절반</strong>만 보인다 (<code>content.slice(0, floor(char_count / 2))</code>).</p><p><strong>왜 글자 수인가</strong></p><ul><li>단어/줄 수 기준은 화면 크기, 폰트, 언어(번역)에 따라 결과가 들쭉날쭉해서 플랫폼 간 일관성이 떨어진다.</li><li><code>char_count</code>로 이미 저장 중이라 기존 시스템과 맞고, 포맷팅으로 더 많이/적게 보이게 하는 악용도 어렵다.</li></ul><p><strong>구현</strong>: <code>lib/feed.ts</code>의 <code>getPreviewContent</code>. 피드에서 확인 완료.</p><h3 id="_7-번역-제한은-채팅에만" tabindex="-1">7. 번역 제한은 채팅에만 <a class="header-anchor" href="#_7-번역-제한은-채팅에만" aria-label="Permalink to &quot;7. 번역 제한은 채팅에만&quot;">​</a></h3><p><strong>결론</strong>: 일기 번역은 항상 무료. 채팅 번역만 하루 N회까지 무료(횟수 미정), 초과분은 유료. 번역 없이 원문으로 채팅하는 건 무제한.</p><p><strong>왜 이렇게 했나</strong></p><ul><li>일기 번역은 &quot;매칭 여부를 결정하는 핵심 진입 경험&quot;이라 막으면 진입장벽이 생긴다.</li><li>채팅 번역은 이미 4단계(둘 다 일기 7개 이상)까지 온 고관여 사용자 대상이라 수용 가능하고, 실시간이라 호출량이 훨씬 많아서 비용 통제가 더 필요하다.</li></ul><p><strong>기각한 안</strong>: 번역 전면 무료 (원래 원칙이었지만 비용 때문에 채팅만 세분화).</p><h3 id="_8-신원-검증-범위" tabindex="-1">8. 신원 검증 범위 <a class="header-anchor" href="#_8-신원-검증-범위" aria-label="Permalink to &quot;8. 신원 검증 범위&quot;">​</a></h3><p><strong>결론</strong>: <strong>학교 소속만</strong> 최소한으로 검증하고, 나머지는 자진 신고 + 사후 신고 체계.</p><table tabindex="0"><thead><tr><th>대상</th><th>검증</th></tr></thead><tbody><tr><td>모든 가입자</td><td>이메일 소유 확인 (Supabase &quot;Confirm email&quot;)</td></tr><tr><td>한국 학생</td><td>+ 이메일이 <code>.ac.kr</code>로 끝나는지</td></tr><tr><td>교환학생</td><td>국가별 학교 이메일 형식이 달라 도메인 자동 검증은 어려움, 이메일 소유 확인만</td></tr><tr><td>성별, 나이 등</td><td>검증 안 함 (자진 신고)</td></tr></tbody></table><p><strong>왜 이렇게 했나</strong></p><ul><li>성별/나이는 이메일 인증으로 증명할 수 없다. 정부 ID 기반 검증은 국가마다 형식이 다르고 민감정보 처리 부담(법적 책임)이 커서 범위 밖이다.</li></ul><p><strong>기각한 안</strong></p><ul><li><strong>에브리타임식 서류 업로드 + 수동 검수</strong>: 가입자가 늘수록 운영 부담이 커져서 소규모 팀엔 비현실적.</li></ul><p><strong>TODO</strong>: 개발 중 꺼둔 &quot;Confirm email&quot;을 <strong>런칭 전에 다시 켜기</strong>, <code>.ac.kr</code> 체크 구현.</p><h3 id="_9-비즈니스-모델" tabindex="-1">9. 비즈니스 모델 <a class="header-anchor" href="#_9-비즈니스-모델" aria-label="Permalink to &quot;9. 비즈니스 모델&quot;">​</a></h3><p><strong>결론</strong>: <strong>핵심 경험은 무료, 부가 기능만 유료.</strong> 런칭 초기에는 부가 기능도 전부 무료로 열고, &quot;이벤트 기간 무료, 이후 일부 유료 전환 예정&quot;이라고 처음부터 공지해 신뢰를 지킨다.</p><table tabindex="0"><thead><tr><th>구분</th><th>항목</th></tr></thead><tbody><tr><td>항상 무료</td><td>일기 작성/조회, 일기 번역, 해금 1~4단계 진입</td></tr><tr><td>유료 후보</td><td>채팅 번역 초과분, 동시 매칭 상한 확장, 하루 징 횟수 확장, 단계 스킵권, 일기 최대 글자 수(600 → 1200자), 프로필 꾸미기/피드 노출</td></tr></tbody></table><p><strong>왜 이렇게 했나</strong></p><ul><li>실제 런칭을 염두에 둔 프로젝트라 수익 구조가 필요하지만, 매칭과 소통의 핵심을 유료로 막으면 사용자 확보가 어렵다.</li><li><strong>단계 스킵권</strong>은 핵심 기능을 막는 게 아니라 &quot;대기 시간을 돈으로 사는&quot; 성격이라 원칙과 덜 충돌한다.</li><li><strong>글자 수는 최대치만 확장</strong>: 최소 200자를 유료로 낮추면 &quot;성의 있는 글쓰기&quot;라는 정체성과 충돌한다.</li><li>구현은 결제 시스템이 생길 때 같이 한다 (<code>users</code>에 유료 여부 필드 + 글자 수 검증 분기).</li></ul><h3 id="_10-글감-프롬프트-기능-보류" tabindex="-1">10. 글감(프롬프트) 기능: 보류 <a class="header-anchor" href="#_10-글감-프롬프트-기능-보류" aria-label="Permalink to &quot;10. 글감(프롬프트) 기능: 보류&quot;">​</a></h3><ul><li>일기 작성용 글감과 2단계의 &quot;앱이 매일 주는 질문&quot;은 같은 메커니즘을 재사용할 수 있다.</li><li>일기 작성용 글감 자체를 넣을지는 별도 결정이 필요해서 <strong>보류</strong>했다. 지금 <code>prompts</code> 테이블은 비워둔 상태.</li></ul><hr><h3 id="아직-안-정한-것" tabindex="-1">아직 안 정한 것 <a class="header-anchor" href="#아직-안-정한-것" aria-label="Permalink to &quot;아직 안 정한 것&quot;">​</a></h3><ul><li>단계 전환 개수 2/4/7의 최종값 (적용 전 재검토)</li><li>채팅 번역 무료 횟수</li><li>번역 API 선택 (파파고/DeepL 등, 팀원과 논의 필요 — 확정된 적 없음)</li><li>글감 기능 도입 여부</li><li>현재 단계를 계산하는 구체적 방법 (<code>zings.matched_at</code> 이후 각자의 일기 수를 세는 로직, <code>zings</code> 구현 때 같이 설계)</li></ul>',56)])])}const _=r(l,[["render",n]]);export{c as __pageData,_ as default};
